(() => {
  const style=document.createElement('style');
  style.textContent='.app{position:relative}.profile-buttons{position:absolute;top:18px;right:16px;display:flex;gap:8px;align-items:center}.profile-logo{width:88px;height:88px;object-fit:contain;background:#000;border:0;border-radius:0;padding:8px;cursor:pointer}.profile-logo img{width:100%;height:100%;object-fit:contain;filter:invert(1) contrast(300%)}.profile-logo.demence{width:164px;height:88px;padding:0}.profile-logo.demence img{filter:grayscale(1) contrast(999%) brightness(160%)}.profile-logo.active{opacity:1}.profile-name{margin:5px 0 0;color:#fff;font-size:.76rem}.brand{padding-right:270px}body.profile-demence{background:#ff72b3}.profile-demence .card{background:#fff;color:#000;border-color:#fff}.profile-demence .card .small,.profile-demence .card label{color:#111}.profile-demence .card select,.profile-demence .card input{background:#fff;color:#000;border-color:#777}.profile-demence .card .secondary{background:#111;color:#fff}.profile-demence .card .status-code.orange{color:#ffd084}.profile-demence .card .status-code.green{color:#91f5ae}.profile-demence .card .status-code.red{color:#ffaaa4}.profile-demence .brand,.profile-demence .profile-name{color:#fff}.profile-demence .profile-logo{background:#ff72b3}.profile-demence .profile-logo img{mix-blend-mode:screen}';
  document.head.append(style);
  const wrap=document.createElement('div');wrap.className='profile-buttons';
  wrap.innerHTML='<button class="profile-logo active" data-profile="fuse" title="Profil Fuse"><img src="fuse-logo.png" alt="Fuse"></button><button class="profile-logo demence" data-profile="la-demence" title="Profil La Demence"><img src="la-demence-logo.png" alt="La Demence"></button>';
  document.querySelector('.app').prepend(wrap);
  const profileName=document.createElement('p');profileName.className='profile-name';profileName.id='profileName';document.querySelector('.brand').after(profileName);
  function choose(profile,notify=true){wrap.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x.dataset.profile===profile));document.body.classList.toggle('profile-demence',profile==='la-demence');localStorage.setItem('fuse-profile',profile);window.FUSE_CURRENT_PROFILE=profile;profileName.textContent=`Profil : ${profile==='fuse'?'Fuse':'La Demence'}`;if(notify)document.dispatchEvent(new CustomEvent('fuse-profile-changed',{detail:{profile}}));}
  wrap.addEventListener('click',e=>{const b=e.target.closest('button');if(b)choose(b.dataset.profile)});
  choose(localStorage.getItem('fuse-profile')||'fuse',false);
})();
